import { BaseLitElement, webComponent } from '@domg-wc/common';
import { vlParagraphStyles } from '@domg-wc/components/atom';
import { CSSResult, html, TemplateResult } from 'lit';

// vlParagraphStyles stijlt de <p>-elementen in de shadow DOM van de component: de classes bold en introduction.
@webComponent('my-component-with-paragraph')
export class MyComponentWithParagraph extends BaseLitElement {
    static get styles(): CSSResult[] {
        return [vlParagraphStyles];
    }

    render(): TemplateResult {
        return html`
            <p class="introduction">Mijn inleiding</p>
        `;
    }
}
